/**
 * WAR control baselines for demo mode.
 *
 * GENERATED from the backend advisory catalogs — WarControlCatalog.java,
 * GcpWarControlCatalog.java and AzureWarControlCatalog.java. Every control id, title,
 * family, severity, attack-path mapping and documentation link is the real reference
 * data the live scan evaluates against, so the demo shows the same baseline a customer
 * would see rather than an invented one.
 *
 * Two deliberate reductions, because this ships in the app bundle for every user:
 *  - `description` is trimmed to its leading sentences instead of the full advisory
 *    implementation steps.
 *  - `businessImpact` paragraphs repeat across a whole family in the advisory, so they
 *    are stored once per provider and referenced by index.
 *
 * Observed state (status, evidence, affected counts) is NOT here — that is synthesised
 * per control in warMockData.ts, which also ports the backend's scoring rules.
 *
 * To refresh after a catalog change, re-run the extraction described in
 * warMockData.ts's header.
 */

/**
 * One control, positionally encoded to keep the fixture compact.
 *
 * [id, ordinal, familyIndex, subCategory, title, description, severity, tools,
 *  reference, controlType, businessImpactIndex, impactLevel, attackPaths, automated]
 */
export type RawWarControl = [
  string, number, number, string, string, string, string, string,
  string, string, number, string, string, 0 | 1,
];

export interface WarBaseline {
  /** Control families, in advisory order. */
  families: string[];
  /** Deduplicated business-impact paragraphs, referenced by index from each row. */
  impacts: string[];
  controls: RawWarControl[];
}


